              <div class="scenario-chip"><div class="scenario">SSP1-2.6</div><div class="temp" style="color:#73c9a9">1.8°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP2-4.5</div><div class="temp" style="color:#ffb547">2.7°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP3-7.0</div><div class="temp" style="color:#f97316">3.6°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP5-8.5</div><div class="temp" style="color:#e84842">4.4°C</div></div>
