        },
        elements: { point: { radius: 4, hoverRadius: 7 }, line: { tension: 0.28, borderWidth: 6 } }
      };
      ChartManager.safeInit('scenarioChart', {
        type: 'line',
        data: {
          labels: labels,
          datasets: [
            { label: 'SSP1-1.9', data: [1.1,1.5,1.55,1.48,1.4], borderColor: '#19b7b1', backgroundColor: 'rgba(25,183,177,.12)' },
            { label: 'SSP1-2.6', data: [1.1,1.65,1.75,1.8,1.8], borderColor: '#73c9a9', backgroundColor: 'rgba(115,201,169,.12)' },
            { label: 'SSP2-4.5', data: [1.1,1.75,2.15,2.45,2.7], borderColor: '#ffb547', backgroundColor: 'rgba(255,181,71,.12)' },
            { label: 'SSP3-7.0', data: [1.1,1.85,2.45,3.05,3.6], borderColor: '#f97316', backgroundColor: 'rgba(249,115,22,.12)' },
            { label: 'SSP5-8.5', data: [1.1,2.0,3.0,3.75,4.4], borderColor: '#e84842', backgroundColor: 'rgba(232,72,66,.12)' }
          ]
        },
        options: options
      });
    }
    window.addEventListener('load', initScenarioChart);
  </script>
