      --text: #f3f7fb; --text-secondary: #aebbd0;
      --accent: #ffb547; --accent-secondary: #19b7b1;
      --positive: #4fd1a5; --negative: #e84842; --warning: #f97316;
    }
    html.theme-light {
      --bg: #f6f8fb; --surface: #ffffff; --surface-hover: #eef3f8;
      --border: rgba(10, 30, 55, 0.13);
      --text: #0b1b2e; --text-secondary: #4d6078;
      --accent: #c3531b; --accent-secondary: #007e8a;
      --positive: #087f5b; --negative: #c92a2a; --warning: #d97706;
    }

    body {
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
      background: var(--bg); color: var(--text);
      line-height: 1.45; -webkit-font-smoothing: antialiased;
      letter-spacing: -0.01em; font-feature-settings: 'cv11', 'ss01';
      transition: background 0.3s, color 0.3s;
      scrollbar-gutter: stable;
    }
    h1,h2,h3,h4,h5,h6 { color: var(--text); letter-spacing: -0.045em; line-height: 1.03; text-wrap: balance; }
    h1 { font-weight: 850; }
    h2 { font-weight: 780; }
    p,li,td,th,span,label { color: var(--text); }
    .text-secondary { color: var(--text-secondary); }
    .card {
      background: linear-gradient(180deg, rgba(255,255,255,0.055), rgba(255,255,255,0.025));
      border: 1px solid var(--border); border-radius: 28px; padding: 30px;
      box-shadow: 0 18px 50px rgba(0,0,0,0.22);
      transition: box-shadow 0.2s ease, transform 0.2s ease;
    }
    .card:hover { box-shadow: 0 0 0 1px var(--border), 0 22px 60px rgba(0,0,0,0.25); }
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(24px); } to { opacity: 1; transform: translateY(0); } }
    @keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
    @keyframes slideInLeft { from { opacity: 0; transform: translateX(-40px); } to { opacity: 1; transform: translateX(0); } }
    @keyframes slideInRight { from { opacity: 0; transform: translateX(40px); } to { opacity: 1; transform: translateX(0); } }
    .animate { animation: fadeInUp 0.6s ease-out both; }
    .animate.delay-1 { animation-delay: 0.1s; } .animate.delay-2 { animation-delay: 0.2s; }
    .animate.delay-3 { animation-delay: 0.3s; } .animate.delay-4 { animation-delay: 0.4s; }
    .animate.delay-5 { animation-delay: 0.5s; } .animate.delay-6 { animation-delay: 0.6s; }
    .reveal { opacity: 1; transform: none; transition: opacity 0.6s ease, transform 0.6s ease; }
    .reveal.visible { opacity: 1; transform: translateY(0); }
    @media (prefers-reduced-motion: reduce) { *, *::before, *::after { animation: none !important; transition: none !important; } .reveal { opacity: 1; transform: none; } }
    @media print {
      body { background: white !important; color: black !important; }
      .viz-menu, .reveal { display: none !important; opacity: 1 !important; transform: none !important; }
      .card { break-inside: avoid; border: 1px solid #ddd; box-shadow: none; }
      * { print-color-adjust: exact; -webkit-print-color-adjust: exact; }
    }
    @page { margin: 0; size: A0 portrait; }

    .viz-menu { position: fixed; top: 16px; right: 16px; z-index: 9999; }
    .viz-menu-toggle { width: 44px; height: 44px; border-radius: 12px; border: 1px solid var(--border); background: var(--surface); color: var(--text); cursor: pointer; font-size: 20px; }
    .viz-menu-dropdown { display: none; position: absolute; right: 0; top: 52px; min-width: 180px; background: var(--surface); border: 1px solid var(--border); border-radius: 14px; padding: 8px; box-shadow: 0 20px 50px rgba(0,0,0,0.35); }
    .viz-menu.open .viz-menu-dropdown { display: block; }
    .viz-menu-dropdown button { width: 100%; padding: 10px 12px; border: 0; border-radius: 10px; background: transparent; color: var(--text); text-align: left; cursor: pointer; font: inherit; }
    .viz-menu-dropdown button:hover { background: var(--surface-hover); }
    .skip-link { position: absolute; left: -999px; top: 12px; background: var(--accent); color: #111; padding: 10px 14px; z-index: 10000; border-radius: 8px; }
    .skip-link:focus { left: 12px; }

    #poster {
      width: 2480px; height: 3508px; overflow: hidden; position: relative;
      background:
        radial-gradient(circle at 82% 3%, rgba(232,72,66,0.34), transparent 23%),
        radial-gradient(circle at 10% 16%, rgba(25,183,177,0.16), transparent 20%),
        radial-gradient(circle at 57% 49%, rgba(249,115,22,0.16), transparent 33%),
        linear-gradient(180deg, #07111f 0%, #091725 45%, #06101b 100%);
    }
    #poster::before {
      content: ""; position: absolute; inset: 0; pointer-events: none; opacity: 0.30;
      background-image:
        linear-gradient(rgba(255,255,255,0.08) 1px, transparent 1px),
        linear-gradient(90deg, rgba(255,255,255,0.08) 1px, transparent 1px);
      background-size: 80px 80px;
      mask-image: linear-gradient(180deg, rgba(0,0,0,0.55), transparent 78%);
    }
    #poster::after {
      content: ""; position: absolute; left: 0; right: 0; top: 0; height: 18px;
      background: linear-gradient(90deg, #204a87, #19b7b1 30%, #ffb547 58%, #f97316 76%, #e84842);
    }
    .wrap { position: relative; z-index: 1; padding: 108px 112px 72px; height: 100%; display: grid; grid-template-rows: auto auto 1fr auto; gap: 34px; }
    .eyebrow { display: inline-flex; gap: 12px; align-items: center; color: #d7e2ef; font-size: 30px; font-weight: 740; letter-spacing: 0.055em; text-transform: uppercase; }
    .eyebrow::before { content: ""; width: 58px; height: 10px; border-radius: 999px; background: linear-gradient(90deg, #19b7b1, #ffb547, #e84842); }
    header { display: grid; grid-template-columns: 1fr 390px; gap: 70px; align-items: start; }
    h1 { font-size: 116px; max-width: 1540px; margin-top: 26px; }
    .lede { font-size: 39px; line-height: 1.25; color: #c9d5e4; max-width: 1510px; margin-top: 30px; }
    .core { color: white; font-weight: 780; }
    .report-box { border-left: 6px solid var(--accent); padding: 28px 28px 30px; background: rgba(255,255,255,0.055); border-radius: 0 26px 26px 0; }
    .report-box .label { font-size: 24px; color: var(--text-secondary); text-transform: uppercase; letter-spacing: 0.08em; font-weight: 760; }
    .report-box .title { margin-top: 18px; font-size: 44px; font-weight: 820; line-height: 1.05; }
    .report-box .meta { margin-top: 22px; color: #c3cfdd; font-size: 25px; line-height: 1.3; }

    .metrics { display: grid; grid-template-columns: repeat(4, 1fr); grid-template-rows: 270px 270px; gap: 22px; }
    .metric { position: relative; overflow: hidden; min-height: 240px; }
    .metric::after { content: ""; position: absolute; inset: auto -40px -55px auto; width: 220px; height: 220px; border-radius: 50%; background: rgba(255,181,71,0.08); }
    .metric .num { font-size: 88px; line-height: .88; font-weight: 880; letter-spacing: -0.07em; color: #fff; }
    .metric .num small { font-size: .44em; letter-spacing: -0.04em; }
    .metric .label { margin-top: 22px; font-size: 26px; line-height: 1.16; color: #c7d2e1; font-weight: 570; }
    .metric .context { margin-top: 16px; font-size: 20px; color: #90a2ba; text-transform: uppercase; letter-spacing: .07em; font-weight: 720; }
    .metric.hot { background: linear-gradient(145deg, rgba(232,72,66,0.42), rgba(13,27,46,0.72)); border-color: rgba(255,181,71,0.35); }
    .metric.urgent { grid-column: span 2; background: linear-gradient(135deg, rgba(232,72,66,0.62), rgba(249,115,22,0.35) 52%, rgba(13,27,46,0.82)); border-color: rgba(255,181,71,0.55); }
    .metric.urgent .num { font-size: 105px; color: #fff6e6; }
    .metric.population { grid-column: span 2; background: linear-gradient(135deg, rgba(255,181,71,0.28), rgba(232,72,66,0.54) 50%, rgba(13,27,46,0.78)); border-color: rgba(232,72,66,0.62); }
    .metric.population .num { font-size: 92px; color: #fff6e6; }

    .content-grid { display: grid; grid-template-columns: 1.05fr .95fr; grid-template-rows: 715px 594px 454px; gap: 24px; min-height: 0; }
    .section-title { display: flex; align-items: center; gap: 18px; margin-bottom: 18px; }
    .section-title .kicker { width: 52px; height: 52px; border-radius: 14px; display: grid; place-items: center; background: rgba(255,181,71,0.14); color: var(--accent); font-weight: 850; font-size: 24px; border: 1px solid rgba(255,181,71,0.25); }
    .section-title h2 { font-size: 42px; }
    .section-copy { color: #c4d0df; font-size: 25px; line-height: 1.29; }
    .section-copy strong { color: #fff; }
    .chart-panel { padding: 30px; }
    .chart-wrap { height: 485px; margin-top: 18px; position: relative; }
    .scenario-note { display: grid; grid-template-columns: repeat(5,1fr); gap: 10px; margin-top: 18px; }
    .scenario-chip { border: 1px solid rgba(255,255,255,0.12); border-radius: 16px; padding: 13px 12px; background: rgba(255,255,255,0.035); }
    .scenario-chip .scenario { font-size: 18px; color: #aebbd0; font-weight: 750; }
    .scenario-chip .temp { font-size: 31px; font-weight: 850; margin-top: 3px; }
    .observed { display: grid; grid-template-rows: auto 1fr; }
    .observed-grid { margin-top: 24px; display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; }
    .obs-item { padding: 22px; border: 1px solid rgba(255,255,255,0.11); border-radius: 22px; background: rgba(255,255,255,0.035); min-height: 132px; }
    .obs-item .value { font-size: 46px; font-weight: 850; color: #fff; }
    .obs-item .name { font-size: 22px; color: #b6c4d5; line-height: 1.2; margin-top: 8px; }
    .risk { grid-row: span 1; background: linear-gradient(160deg, rgba(13,27,46,0.92), rgba(232,72,66,0.18)); }
    .risk-highlight { display: grid; grid-template-columns: 260px 1fr; gap: 28px; align-items: center; margin-top: 22px; }
    .people-icon { width: 250px; height: 250px; border-radius: 50%; background: radial-gradient(circle, rgba(255,181,71,0.34), rgba(232,72,66,0.15)); display: grid; place-items: center; border: 1px solid rgba(255,181,71,.35); }
    .people-icon svg { width: 160px; height: 160px; fill: #ffd18a; opacity: .95; }
    .risk-stat { font-size: 72px; line-height: .95; font-weight: 890; color: #fff2dc; letter-spacing: -0.06em; }
    .risk-text { font-size: 27px; color: #ccd7e5; margin-top: 14px; line-height: 1.22; }
    .risk-list { display: grid; grid-template-columns: repeat(3,1fr); gap: 15px; margin-top: 28px; }
    .risk-list div { padding: 18px; background: rgba(255,255,255,0.045); border: 1px solid rgba(255,255,255,0.1); border-radius: 18px; }
    .risk-list h3 { font-size: 24px; color: #ffd18a; margin-bottom: 8px; }
    .risk-list p { color: #bdcadb; font-size: 20px; line-height: 1.22; }
    .pathways { grid-column: 2; }
    .pathway-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 24px; }
    .target-card { padding: 25px; border-radius: 24px; border: 1px solid rgba(255,255,255,0.12); background: rgba(255,255,255,0.04); }
    .target-card .target { font-size: 58px; font-weight: 870; color: #fff; }
    .target-card .deadline { color: #ffcc82; font-size: 25px; font-weight: 760; margin-top: 6px; }
    .target-card p { color: #bdcadb; font-size: 22px; line-height: 1.23; margin-top: 12px; }
    .lever-row { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin-top: 22px; }
    .lever { padding: 15px; border-radius: 16px; background: rgba(25,183,177,.09); border: 1px solid rgba(25,183,177,.22); color: #d5ffff; font-size: 18px; font-weight: 720; text-align: center; }
    .window { grid-column: 1 / -1; background: linear-gradient(100deg, rgba(232,72,66,0.33), rgba(249,115,22,0.18) 36%, rgba(13,27,46,0.82)); display: grid; grid-template-columns: 1.25fr .75fr; gap: 38px; align-items: center; border-color: rgba(255,181,71,.38); }
    .window h2 { font-size: 62px; margin-bottom: 18px; }
    .window p { font-size: 30px; line-height: 1.25; color: #d6e0ec; }
    .urgency-bars { display: grid; gap: 16px; }
    .bar-row { display: grid; grid-template-columns: 190px 1fr 105px; gap: 18px; align-items: center; font-size: 22px; color: #cbd6e5; }
    .bar-track { height: 28px; border-radius: 999px; background: rgba(255,255,255,0.09); overflow: hidden; border: 1px solid rgba(255,255,255,0.11); }
    .bar-fill { height: 100%; border-radius: 999px; background: linear-gradient(90deg, #19b7b1, #ffb547, #e84842); }
    .footer { display: grid; grid-template-columns: 1fr auto; gap: 34px; align-items: end; color: #93a4ba; font-size: 20px; border-top: 1px solid rgba(255,255,255,0.12); padding-top: 22px; }
    .footer strong { color: #d9e4f1; }
    .source { max-width: 1450px; }
    .tagline { font-size: 26px; font-weight: 820; color: #fff; text-align: right; }
    canvas { width: 100% !important; height: 100% !important; }
  </style>
</head>
<body>
  <a class="skip-link" href="#main-content">Skip to content</a>
  <div class="viz-menu" id="vizMenu">
    <button class="viz-menu-toggle" aria-label="Open visualization menu" onclick="toggleMenu()">☰</button>
    <div class="viz-menu-dropdown">
      <button onclick="downloadImage()">Download PNG</button>
      <button onclick="window.print()">Print</button>
      <button onclick="toggleTheme()">Toggle theme</button>
    </div>
  </div>

  <main id="main-content">
    <div id="poster">
      <div class="wrap">
        <section class="hero animate" aria-labelledby="poster-title">
          <header>
            <div>
              <div class="eyebrow">IPCC AR6 Synthesis Report · 2023</div>
              <h1 id="poster-title">Climate Change 2023: Key Findings</h1>
              <p class="lede"><span class="core">Human-caused climate change is unequivocal</span>, already affecting every region on Earth, and the window for meaningful action is rapidly closing.</p>
            </div>
            <aside class="report-box" aria-label="Poster context">
              <div class="label">Conference Poster</div>
              <div class="title">Evidence · Pathways · Urgency</div>
              <div class="meta">Academic, data-forward visual synthesis for researchers and policymakers.</div>
            </aside>
          </header>
        </section>

        <section class="metrics animate delay-1" aria-labelledby="metrics-title">
          <h2 id="metrics-title" style="position:absolute;left:-9999px;">Seven headline metrics</h2>
          <article class="metric card hot"><div class="num">1.1<small>°C</small></div><div class="label">Global surface temperature increase</div><div class="context">2011–2020 vs 1850–1900</div></article>
          <article class="metric card"><div class="num">410<small> ppm</small></div><div class="label">Atmospheric CO₂ concentration</div><div class="context">Highest in ≥2 million years</div></article>
          <article class="metric card"><div class="num">59<small> GtCO₂e</small></div><div class="label">Global GHG emissions</div><div class="context">2019 annual total</div></article>
          <article class="metric card"><div class="num">500<small> GtCO₂</small></div><div class="label">Remaining carbon budget for 1.5°C</div><div class="context">50% likelihood, from 2020</div></article>
          <article class="metric card urgent"><div class="num">43<small>%</small></div><div class="label">Required global GHG reduction by 2030 for a 1.5°C pathway</div><div class="context">Below 2019 levels · no/limited overshoot</div></article>
          <article class="metric card"><div class="num">0.20<small> m</small></div><div class="label">Observed sea level rise</div><div class="context">1901–2018</div></article>
          <article class="metric card population"><div class="num">3.3–3.6<small> bn</small></div><div class="label">People exposed to severe climate hazards</div><div class="context">Highly vulnerable contexts</div></article>
        </section>

        <div class="content-grid">
          <section class="card observed reveal" aria-labelledby="observed-title">
            <div class="section-title"><div class="kicker">01</div><h2 id="observed-title">Observed Changes and Current State</h2></div>
            <p class="section-copy">Warming, greenhouse gas concentrations, sea level rise, and cryosphere change are documented across multiple indicators. Extreme weather has increased in frequency and intensity in every region, with clear attribution to human influence.</p>
            <div class="observed-grid">
              <div class="obs-item"><div class="value">+1.1°C</div><div class="name">Warming above pre-industrial baseline</div></div>
              <div class="obs-item"><div class="value">~40%</div><div class="name">September Arctic sea-ice area loss, 1979–2020</div></div>
              <div class="obs-item"><div class="value">410 ppm</div><div class="name">CO₂ concentration reached in 2019</div></div>
              <div class="obs-item"><div class="value">~0.20 m</div><div class="name">Global mean sea-level rise, 1901–2018</div></div>
            </div>
          </section>

          <section class="card chart-panel reveal" aria-labelledby="projection-title">
            <div class="section-title"><div class="kicker">02</div><h2 id="projection-title">Future Projections Under SSP Scenarios</h2></div>
            <p class="section-copy">Pathway choices define late-century warming: very low emissions hold best-estimate warming near <strong>1.4°C</strong>, while very high emissions reach <strong>4.4°C</strong> by 2100.</p>
            <div class="chart-wrap"><canvas id="scenarioChart" role="img" aria-label="Projected global warming by 2100 across SSP scenarios from 1.4 to 4.4 degrees Celsius"></canvas></div>
            <div class="scenario-note" aria-hidden="true">
              <div class="scenario-chip"><div class="scenario">SSP1-1.9</div><div class="temp" style="color:#19b7b1">1.4°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP1-2.6</div><div class="temp" style="color:#73c9a9">1.8°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP2-4.5</div><div class="temp" style="color:#ffb547">2.7°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP3-7.0</div><div class="temp" style="color:#f97316">3.6°C</div></div>
              <div class="scenario-chip"><div class="scenario">SSP5-8.5</div><div class="temp" style="color:#e84842">4.4°C</div></div>
            </div>
          </section>

          <section class="card risk reveal" aria-labelledby="risk-title">
            <div class="section-title"><div class="kicker">03</div><h2 id="risk-title">Risks, Vulnerabilities, and Cascading Impacts</h2></div>
            <div class="risk-highlight">
              <div class="people-icon" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M16 11c1.66 0 2.99-1.34 2.99-3S17.66 5 16 5s-3 1.34-3 3 1.34 3 3 3Zm-8 0c1.66 0 2.99-1.34 2.99-3S9.66 5 8 5 5 6.34 5 8s1.34 3 3 3Zm0 2c-2.33 0-7 1.17-7 3.5V19h14v-2.5C15 14.17 10.33 13 8 13Zm8 0c-.29 0-.62.02-.97.05 1.16.84 1.97 1.97 1.97 3.45V19h6v-2.5c0-2.33-4.67-3.5-7-3.5Z"/></svg></div>
              <div><div class="risk-stat">3.3–3.6 billion people</div><div class="risk-text">live in contexts highly vulnerable to climate change, where hazards interact with poverty, inequality, and ecosystem degradation.</div></div>
            </div>
            <div class="risk-list">
              <div><h3>Food</h3><p>Crop yield growth has slowed in many regions; tropical fisheries productivity is declining.</p></div>
              <div><h3>Water</h3><p>Over half the world experiences severe water scarcity for at least one month per year.</p></div>
              <div><h3>Health</h3><p>Heat-related mortality and vector-borne disease ranges are expanding.</p></div>
            </div>
          </section>

          <section class="card pathways reveal" aria-labelledby="pathways-title">
            <div class="section-title"><div class="kicker">04</div><h2 id="pathways-title">Mitigation and Adaptation Pathways</h2></div>
            <p class="section-copy">Limiting warming requires rapid, deep, and sustained emissions reductions across all sectors, alongside scaled adaptation and resilience investment.</p>
            <div class="pathway-grid">
              <div class="target-card"><div class="target">1.5°C</div><div class="deadline">−43% by 2030 · net zero CO₂ ~2050</div><p>No or limited overshoot requires immediate global GHG decline from 2019 levels.</p></div>
              <div class="target-card"><div class="target">2°C</div><div class="deadline">−27% by 2030 · net zero CO₂ ~2070</div><p>Lower ambition raises residual risks and adaptation burdens.</p></div>
            </div>
            <div class="lever-row"><div class="lever">Clean energy</div><div class="lever">Electrification</div><div class="lever">Demand efficiency</div><div class="lever">Carbon sinks</div></div>
          </section>

          <section class="card window reveal" aria-labelledby="window-title">
            <div>
              <div class="section-title"><div class="kicker">05</div><h2 id="window-title">The Narrowing Window for Action</h2></div>
              <p>Choices made in this decade determine whether warming can be held to 1.5°C or 2°C. Delayed action increases costs, locks in high-carbon infrastructure, and reduces feasibility. Adaptation finance alone remains short by a factor of <strong>3–6×</strong>.</p>
            </div>
            <div class="urgency-bars" aria-label="Urgency summary">
              <div class="bar-row"><span>Observed warming</span><div class="bar-track"><div class="bar-fill" style="width:25%"></div></div><strong>1.1°C</strong></div>
              <div class="bar-row"><span>1.5°C threshold</span><div class="bar-track"><div class="bar-fill" style="width:34%"></div></div><strong>near term</strong></div>
              <div class="bar-row"><span>High emissions</span><div class="bar-track"><div class="bar-fill" style="width:100%"></div></div><strong>4.4°C</strong></div>
              <div class="bar-row"><span>2030 reduction</span><div class="bar-track"><div class="bar-fill" style="width:43%"></div></div><strong>43%</strong></div>
            </div>
          </section>
        </div>

        <section class="footer" aria-label="Source and citation">
          <div class="source"><strong>Source:</strong> IPCC, 2023. <em>AR6 Synthesis Report: Climate Change 2023.</em> Intergovernmental Panel on Climate Change. Values shown are best estimates or approximate headline values from the synthesis brief.</div>
          <div class="tagline">Immediate · Deep · Sustained reductions</div>
        </section>
      </div>
    </div>
  </main>

  <script>
    function toggleMenu() { document.getElementById('vizMenu').classList.toggle('open'); }
    function toggleTheme() {
      var html = document.documentElement;
      html.classList.toggle('theme-light'); html.classList.toggle('theme-dark');
    }
    function downloadImage() {
      var node = document.getElementById('poster');
      htmlToImage.toPng(node, { pixelRatio: 1, cacheBust: true, backgroundColor: '#07111f' })
        .then(function(dataUrl) {
          var link = document.createElement('a');
          link.download = 'ipcc-ar6-key-findings-poster.png';
          link.href = dataUrl;
          link.click();
        })
        .catch(function(error) { console.error('PNG export failed', error); });
    }
    var revealObserver = { observe: function(el) { el.classList.add('visible'); } };
    document.querySelectorAll('.reveal').forEach(function(el) { revealObserver.observe(el); });
